#include "std_include.h"
#include "cuda_runtime.h"
#include "vertexQuadraticEnergy.h"
#include "EnergyMinimizerFIRE2D.h"
#include "vertexTrajectoryDatabase.h"
#include <filesystem>
#include <glob.h>
#include <chrono>
#include <cstdio>
#include <vector>

// Generated by Claude Code. 2026-10-21
// Per-cell shapes of quenched vertex production snapshots. The quench is the
// own-p0 quench of vertexProductionRigidQuench (same FIRE recipe, chunks and
// stop rules), so E per snapshot can be checked against its CSV:
//   E = sum_i KA (A_i - 1)^2 + (P_i - p0)^2, KA = 1 by default (production),
//   dt = 1e-3, dtMax = 50 dt, alphaStart = 0.1, alphaDec = 0.99,
//   dtInc = 1.1, dtDec = 0.5, NMin = 5, force cutoff 1e-12, T1s on (l_T1 = 0.01),
//   chunks of 1e4 steps, stop once E < 1e-14 (floppy) or E > 1e-6 changes by
//   < 1e-10 relative over a chunk (plateau), at most 1e6 steps.
// Per (p0, T): last nKeep records of each idx (default 3, idx = 0..9).
// After each quench, one row per cell: number of sides z, dA = A - 1,
// dP = P - p0, and the cell position (mean of its vertices).
// Output under productionRuns/quenchCells/:
//   quenchCells_*.csv         idx,rec,cell,z,dA,dP,x,y
//   quenchCellsSummary_*.csv  one row per snapshot (columns of the rigidQuench CSV)

class countingFIRE : public EnergyMinimizerFIRE
    {
    public:
        countingFIRE(shared_ptr<Simple2DModel> system, bool useGPU) : EnergyMinimizerFIRE(system,useGPU){};
        int getIterations(){return iterations;};
    };

static string findTrajectory(const string &dir, int N, double p0, double T, int idx)
    {
    char globpat[1024];
    snprintf(globpat, sizeof(globpat),
             "%sglassyDynamics_N%i_p%.4f_T%.8f_waitingTime*_idx%i.nc",
             dir.c_str(), N, p0, T, idx);
    glob_t g;
    g.gl_offs = 0;
    int rc = glob(globpat, 0, NULL, &g);
    string out;
    if (rc == 0 && g.gl_pathc > 0)
        out = g.gl_pathv[0];
    globfree(&g);
    return out;
    }

static void cellSides(shared_ptr<VertexQuadraticEnergy> avm, vector<int> &z)
    {
    ArrayHandle<int> h_cvn(avm->cellVertexNum,access_location::host,access_mode::read);
    z.assign(h_cvn.data, h_cvn.data + avm->Ncells);
    }

static double hexFraction(const vector<int> &z)
    {
    int n6 = 0;
    for (int zi : z)
        if (zi == 6)
            n6 += 1;
    return (double)n6 / (double)z.size();
    }

int main(int argc, char *argv[])
    {
    int numpts = 4096;
    int USE_GPU = -1;
    double T = 0.01;
    double p0 = 3.8;
    int nKeep = 3;
    int idxLo = 0;
    int idxHi = 9;
    double KA = 1.0;
    double t1t = 0.01;
    double dt = 0.001;
    double forceCutoff = 1e-12;
    int maxIterations = 1000000;
    int chunk = 10000;
    int oldCap = 100000;
    double eRigid = 1e-10;
    double eFloppyStop = 1e-14;
    double ePlateauMin = 1e-6;
    double plateauTol = 1e-10;

    int c;
    while ((c = getopt(argc, argv, "n:g:p:v:s:i:j:k:e:r:x:c:")) != -1)
        switch (c)
            {
            case 'n': numpts = atoi(optarg); break;
            case 'g': USE_GPU = atoi(optarg); break;
            case 'p': p0 = atof(optarg); break;
            case 'v': T = atof(optarg); break;
            case 's': nKeep = atoi(optarg); break;
            case 'i': idxLo = atoi(optarg); break;
            case 'j': idxHi = atoi(optarg); break;
            case 'k': KA = atof(optarg); break;
            case 'e': dt = atof(optarg); break;
            case 'r': forceCutoff = atof(optarg); break;
            case 'x': maxIterations = atoi(optarg); break;
            case 'c': chunk = atoi(optarg); break;
            case '?':
                return 1;
            default:
                abort();
            };

    bool reproducible = true;
    bool initializeGPU = true;
    bool gpu = chooseGPU(USE_GPU);
    if (!gpu)
        initializeGPU = false;

    const char *scratchEnv = getenv("CELLGPU_SCRATCH");
    string scratch = scratchEnv ? scratchEnv : "/scratch/bbtm/cli6/glassyDynamics/data";

    char loadfolder[512];
    char savefolder[512];
    char cellName[768];
    char sumName[768];
    snprintf(loadfolder, sizeof(loadfolder), "%s/N%i/vertex/productionRuns/p%.3f/",
             scratch.c_str(), numpts, p0);
    snprintf(savefolder, sizeof(savefolder), "%s/N%i/vertex/productionRuns/quenchCells/",
             scratch.c_str(), numpts);
    snprintf(cellName, sizeof(cellName), "%squenchCells_N%i_p%.4f_T%.8f_KA%.4f_idx%i-%i.csv",
             savefolder, numpts, p0, T, KA, idxLo, idxHi);
    snprintf(sumName, sizeof(sumName), "%squenchCellsSummary_N%i_p%.4f_T%.8f_KA%.4f_idx%i-%i.csv",
             savefolder, numpts, p0, T, KA, idxLo, idxHi);
    std::filesystem::create_directories(savefolder);

    cout << "p0 = " << p0 << " T = " << T << " KA = " << KA << " nKeep = " << nKeep
         << " idx = " << idxLo << ".." << idxHi << endl;
    cout << "FIRE dt = " << dt << " force cutoff = " << forceCutoff << " max iterations = " << maxIterations
         << " l_T1 = " << t1t << endl;
    cout << "load dir " << loadfolder << endl;
    cout << "write " << cellName << endl;
    cout << "write " << sumName << endl;

    FILE *outCells = fopen(cellName, "w");
    FILE *outSum = fopen(sumName, "w");
    if (!outCells || !outSum)
        {
        cout << "cannot open output files" << endl;
        return 1;
        }
    fprintf(outCells, "idx,rec,cell,z,dA,dP,x,y\n");
    fprintf(outSum, "p0,T,idx,rec,time,KA,E0,E1e5,E,maxF,iters,status,rigid,p6_0,p6,nZchanged,sec\n");
    fflush(outCells);
    fflush(outSum);

    int Nvert = 2 * numpts;
    shared_ptr<VertexQuadraticEnergy> avm =
        make_shared<VertexQuadraticEnergy>(numpts, 1.0, p0, reproducible, false, initializeGPU);
    if (!initializeGPU)
        avm->setCPU();

    int nMissing = 0;
    int nShort = 0;
    int nQuench = 0;
    for (int idx = idxLo; idx <= idxHi; ++idx)
        {
        string loaddataname = findTrajectory(string(loadfolder), numpts, p0, T, idx);
        if (loaddataname.empty())
            {
            cout << "missing idx=" << idx << endl;
            nMissing += 1;
            continue;
            }
        cout << "reading " << loaddataname << endl;
        vertexTrajectoryDatabase traj(Nvert, loaddataname, NcFile::ReadOnly);
        int nrec = traj.GetNumRecs();
        if (nrec < nKeep)
            {
            cout << "records = " << nrec << " < " << nKeep << "; skip idx=" << idx << endl;
            nShort += 1;
            continue;
            }
        for (int rec = nrec - nKeep; rec < nrec; ++rec)
            {
            auto t0 = std::chrono::steady_clock::now();
            traj.readState(avm, rec, true);
            double time = avm->currentTime;
            avm->setModuliUniform(KA, 1.0);
            avm->setCellPreferencesUniform(1.0, p0);
            avm->setT1Threshold(t1t);
            vector<int> z0, z1;
            cellSides(avm, z0);
            double E0 = avm->computeEnergy();

            shared_ptr<countingFIRE> fire = make_shared<countingFIRE>(avm, initializeGPU);
            if (!initializeGPU)
                fire->setCPU();
            fire->setDeltaT(dt);
            fire->setAlphaStart(0.1);
            fire->setDeltaTMax(50 * dt);
            fire->setDeltaTInc(1.1);
            fire->setDeltaTDec(0.5);
            fire->setAlphaDec(0.99);
            fire->setNMin(5);
            fire->setForceCutoff(forceCutoff);

            double E = E0;
            double E1e5 = E0;
            double maxF = 0.0;
            string status = "maxit";
            int done = 0;
            while (done < maxIterations)
                {
                fire->setMaximumIterations(min(done + chunk, maxIterations));
                fire->minimize();
                int now = fire->getIterations();
                double Eprev = E;
                E = avm->computeEnergy();
                maxF = sqrt(fire->getMaxForce());
                if (done < oldCap && now >= oldCap)
                    E1e5 = E;
                done = now;
                if (E < eFloppyStop)
                    {
                    status = "floppy";
                    break;
                    }
                if (maxF <= forceCutoff)
                    {
                    status = "conv";
                    break;
                    }
                if (E > ePlateauMin && fabs(Eprev - E) < plateauTol * E)
                    {
                    status = "plateau";
                    break;
                    }
                }
            if (done < oldCap)
                E1e5 = E;

            // computeEnergy above left AreaPeri at the quenched vertices
            cellSides(avm, z1);
            int nZchanged = 0;
            for (size_t cc = 0; cc < z0.size(); ++cc)
                if (z0[cc] != z1[cc])
                    nZchanged += 1;
            avm->getCellPositions();
            {
            ArrayHandle<double2> h_AP(avm->returnAreaPeri(),access_location::host,access_mode::read);
            ArrayHandle<double2> h_cp(avm->cellPositions,access_location::host,access_mode::read);
            for (int cc = 0; cc < avm->Ncells; ++cc)
                fprintf(outCells, "%i,%i,%i,%i,%.6e,%.6e,%.5f,%.5f\n",
                        idx, rec, cc, z1[cc], h_AP.data[cc].x - 1.0, h_AP.data[cc].y - p0,
                        h_cp.data[cc].x, h_cp.data[cc].y);
            }
            fflush(outCells);

            bool rigid = E > eRigid;
            double sec = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
            fprintf(outSum, "%.3f,%.8f,%i,%i,%.6f,%.4f,%.10g,%.10g,%.10g,%.6g,%i,%s,%i,%.6f,%.6f,%i,%.2f\n",
                    p0, T, idx, rec, time, KA, E0, E1e5, E, maxF, done, status.c_str(), rigid ? 1 : 0,
                    hexFraction(z0), hexFraction(z1), nZchanged, sec);
            fflush(outSum);
            nQuench += 1;
            printf("idx %i rec %i: E %.4g -> %.4g, maxF %.3g, %i iterations, %s, %.1f s\n",
                   idx, rec, E0, E, maxF, done, status.c_str(), sec);
            }
        }

    fclose(outCells);
    fclose(outSum);
    cout << "n_quench = " << nQuench << " n_missing = " << nMissing << " n_short = " << nShort << endl;
    if (initializeGPU)
        cudaDeviceReset();
    return nQuench > 0 ? 0 : 1;
    }
